        m = re.search(r'<native-record>([^<]+)</native-record>', t)
        if m: return clean(m.group(1))
    elif ext == 'html':
        m = re.search(r'<dl>.*?</dl><p>([^<]+)</p>', t, re.S)
        if m: return clean(m.group(1))
    elif ext == 'pdf':
        m = re.search(r'\(NATIVE RECORD\) Tj\s*T\*\s*\n((?:\([^)]*\) Tj\s*T\*\s*)+)', t)
        if m:
            parts = re.findall(r'\(([^)]*)\) Tj', m.group(1))
            return clean(' '.join(parts))
    return None

